-- Counts for verification
select 'ingredients' as kind, count(*)::int as n from public.ingredients i join public.tenants t on t.id = i.tenant_id where t.slug = 'liaco'
union all select 'recipes', count(*)::int from public.recipes r join public.tenants t on t.id = r.tenant_id where t.slug = 'liaco'
union all select 'recipe_lines', count(*)::int from public.recipe_lines rl join public.tenants t on t.id = rl.tenant_id where t.slug = 'liaco'
union all select 'products', count(*)::int from public.products p join public.tenants t on t.id = p.tenant_id where t.slug = 'liaco'
union all select 'products_published', count(*)::int from public.products p join public.tenants t on t.id = p.tenant_id where t.slug = 'liaco' and p.is_published
union all select 'pizza_variants', count(*)::int from public.product_recipe_variants v join public.tenants t on t.id = v.tenant_id where t.slug = 'liaco';